  var BOOK_CONTEXT_ORDER = ["١كورنثوس","٢كورنثوس","١تسالونيكي","٢تسالونيكي","١تيموثاوس","٢تيموثاوس",
    "١بطرس","٢بطرس","١يوحنا","٢يوحنا","٣يوحنا","متى","مرقس","لوقا","يوحنا","أعمال","رومية",
    "غلاطية","أفسس","فيلبي","كولوسي","تيطس","فليمون","عبرانيين","يعقوب","بطرس","يهوذا","الرؤيا","مزمور"];

  function getBookContext(r){
    var haystack = "";
    if(r.gospelRef) haystack += r.gospelRef + " ";
    if(r.shortRef) haystack += r.shortRef + " ";
    if(r.psalmRef) haystack += r.psalmRef + " ";
    if(!haystack) return null;
    for(var i=0;i<BOOK_CONTEXT_ORDER.length;i++){
      var key = BOOK_CONTEXT_ORDER[i];
      if(haystack.indexOf(key) !== -1) return BOOK_CONTEXT[key];
    }
    return null;
  }

  /* v1.0: set by renderContent() for the currently-displayed day, read by readingCardHTML()
     so the per-reading context line can show the weekly/seasonal position and the "why this
     reading" note without changing readingCardHTML's own (r) signature. */
  var currentMeditationForCard = null;
  var currentCopticMonthForCard = null;
  var currentCopticDayForCard = null;

  function buildContextLine(r){
    var html = "";
    var bookCtx = getBookContext(r);
    if(bookCtx){
      html += (
        '<div class="context-line book-info">' +
          '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M12 2a7 7 0 00-7 7c0 5 7 13 7 13s7-8 7-13a7 7 0 00-7-7z"/><circle cx="12" cy="9" r="2"/></svg>' +
          '<div class="book-info-body">' +
            '<div class="book-info-title">نبذة عن السفر<span class="fn">٥</span></div>' +
            '<dl class="book-info-fields">' +
              '<div><dt>الكاتب</dt><dd>'+bookCtx.author+'</dd></div>' +
              '<div><dt>زمن الكتابة</dt><dd>'+bookCtx.date+'</dd></div>' +
              '<div><dt>مكان الكتابة</dt><dd>'+bookCtx.place+'</dd></div>' +
              '<div><dt>الغرض من الكتابة</dt><dd>'+bookCtx.purpose+'</dd></div>' +
            '</dl>' +
            '<p class="book-info-summary">'+bookCtx.summary+'</p>' +
          '</div>' +
        '</div>'
      );
    }
    if(currentCopticMonthForCard && currentCopticDayForCard){
      var weekOrdinal = Math.min(Math.ceil(currentCopticDayForCard/7), 5);
      var monthName = COPTIC_MONTHS[Math.min(currentCopticMonthForCard,13) - 1];
      html += '<div class="context-line"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M3 10h18M7 3v4M17 3v4"/><rect x="3" y="6" width="18" height="15" rx="2"/></svg><span>هذه القراءة في الأسبوع '+toArabicDigits(weekOrdinal)+' من شهر '+monthName+' القبطي.</span></div>';
    }
    return html;
  }

